@@ -44,9 +44,9 @@
 function audio(){if(!audioCtx)audioCtx=new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();return audioCtx}
 function tone(freq=440,duration=.08,volume=.05){if(!soundOn)return;try{const c=audio(),o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(volume,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+duration);o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+duration)}catch(e){}}
 function makeNotes(){const diff=$('#difficulty').value;beatMs=diff==='chill'?650:diff==='spicy'?480:570;const p=moves[selected].pattern,arr=[];for(let i=0;i<16;i++){let lane;if(p===0)lane=[0,1,2,1,3,2,1,0,2,3,1,2,0,1,3,2][i];else if(p===1)lane=(i*3+Math.floor(i/4))%4;else if(p===2)lane=[0,2,1,3,1,2,0,3,2,1,3,0,1,2,0,3][i];else lane=[3,3,1,0,2,3,1,1,2,0,3,2,1,3,0,2][i];if(diff==='spicy'&&i%4===3)lane=(lane+1)%4;arr.push({lane,time:1000+i*beatMs,hit:false})}return arr}
 function begin(){if(playing||hp<=0||playerHp<=0)return;audio();playing=true;hitCount=0;perfect=0;judged=0;combo=0;$('#combo').textContent='✦ 0 COMBO';notes=makeNotes();startTime=performance.now();$('#start').disabled=true;$('#start').textContent='♫  RIFF IN PROGRESS';$('#progress').textContent='GET READY…';$('#status').textContent='COUNTING IN';$('#log').textContent=`${moves[selected].name}! Get ready to hit the beat…`;moveBtns.forEach(b=>b.disabled=true);notes.forEach(n=>{const el=document.createElement('i');el.className='note';el.style.setProperty('--lane',laneColors[n.lane]);el.dataset.index=notes.indexOf(n);el.style.top='-22px';lanes[n.lane].appendChild(el);n.el=el});tone(660,.1);setTimeout(()=>tone(740,.1),beatMs/2);raf=requestAnimationFrame(tick)}
-function tick(now){if(!playing)return;const elapsed=now-startTime,travel=1250;let remaining=0;notes.forEach(n=>{if(n.hit)return;const dt=n.time-elapsed;if(dt < -170){n.hit=true;judged++;combo=0;$('#combo').textContent='✦ 0 COMBO';n.el?.remove();$('#feedback').textContent='MISS';$('#feedback').style.color='#ff7985';setTimeout(()=>$('#feedback').textContent='',320);tone(120,.12,.02);return}remaining++;if(n.el){const y=35+(1-dt/travel)*73;n.el.style.top=`${Math.max(-20,Math.min(83,y))}px`}});const next=notes.find(n=>!n.hit);$('#progress').textContent=next?`${Math.max(1,Math.ceil((notes.length-judged)/4))} BARS · ${Math.max(0,Math.ceil((next.time-elapsed)/1000))}s`:'WRAPPING UP…';if(judged===notes.length){playing=false;setTimeout(finishTurn,450);return}raf=requestAnimationFrame(tick)}
+function tick(now){if(!playing)return;const elapsed=now-startTime,travel=1250;let remaining=0;notes.forEach(n=>{if(n.hit)return;const dt=n.time-elapsed;if(dt < -170){n.hit=true;judged++;combo=0;$('#combo').textContent='✦ 0 COMBO';n.el?.remove();$('#feedback').textContent='MISS';$('#feedback').style.color='#ff7985';setTimeout(()=>$('#feedback').textContent='',320);tone(120,.12,.02);return}remaining++;if(n.el){const y=60-dt/travel*80;n.el.style.top=`${Math.max(-20,Math.min(83,y))}px`}});const next=notes.find(n=>!n.hit);$('#progress').textContent=next?`${Math.max(1,Math.ceil((notes.length-judged)/4))} BARS · ${Math.max(0,Math.ceil((next.time-elapsed)/1000))}s`:'WRAPPING UP…';if(judged===notes.length){playing=false;setTimeout(finishTurn,450);return}raf=requestAnimationFrame(tick)}
 function hit(lane){if(!playing)return;const elapsed=performance.now()-startTime,possible=notes.filter(n=>!n.hit&&n.lane===lane).sort((a,b)=>Math.abs(a.time-elapsed)-Math.abs(b.time-elapsed))[0];if(!possible||Math.abs(possible.time-elapsed)>175){tone(190,.06,.02);return}const delta=Math.abs(possible.time-elapsed),grade=delta<62?'PERFECT':delta<115?'GREAT':'GOOD';possible.hit=true;judged++;hitCount++;combo++;best=Math.max(best,combo);if(grade==='PERFECT')perfect++;const pts=grade==='PERFECT'?100:grade==='GREAT'?70:45;score+=pts+Math.min(combo*2,50);$('#score').textContent=String(score).padStart(4,'0');$('#best').textContent=best+'×';$('#combo').textContent=`✦ ${combo} COMBO`;$('#feedback').textContent=grade;$('#feedback').style.color=grade==='PERFECT'?'#d4ff70':grade==='GREAT'?'#70dfba':'#ffffff';setTimeout(()=>{if($('#feedback').textContent===grade)$('#feedback').textContent=''},260);lanes[lane].classList.add('hit');setTimeout(()=>lanes[lane].classList.remove('hit'),100);possible.el?.remove();tone([350,440,550,660][lane]+(grade==='PERFECT'?150:0),.09,.035)}
 function keydown(e){const key=e.key.toLowerCase(),i=keys.indexOf(key);if(i>=0){e.preventDefault();hit(i)}}window.addEventListener('keydown',keydown);
 lanes.forEach((lane,i)=>lane.addEventListener('pointerdown',()=>hit(i)));
 function finishTurn(){const accuracy=hitCount/notes.length;const damage=Math.round((8+accuracy*24)*moves[selected].power);hp=Math.max(0,hp-damage);$('#foe-hp').style.width=(hp/42*100)+'%';$('#foe-hp-text').textContent=`${hp} / 42 HP`;$('#foe').classList.remove('hurt');$('#hero').classList.add('attack');setTimeout(()=>$('#hero').classList.remove('attack'),600);$('#flash').classList.remove('on');void $('#flash').offsetWidth;$('#flash').classList.add('on');$('#foe').classList.add('hurt');setTimeout(()=>$('#foe').classList.remove('hurt'),450);const grade=accuracy>.88?'Pitch perfect!':accuracy>.62?'Great riff!':'Keep practicing!';$('#log').textContent=`${grade} ${moves[selected].name} dealt ${damage} damage! (${Math.round(accuracy*100)}% accuracy)`;$('#status').textContent=`${hitCount}/${notes.length} NOTES HIT`;tone(accuracy>.65?720:240,.3,.06);turn++;if(hp<=0){setTimeout(()=>endGame(true),700);return}if(accuracy<.55){setTimeout(()=>{playerHp=Math.max(0,playerHp-8);$('#hero-card-hp').style.width=(playerHp/60*100)+'%';$('#hero-hp-text').textContent=`${playerHp} / 60 HP`;$('#foe').classList.add('attack');setTimeout(()=>$('#foe').classList.remove('attack'),550);$('#log').textContent='Chompuff counterattacks! You took 8 damage.';tone(150,.3,.06);if(playerHp<=0){setTimeout(()=>endGame(false),600)}else readyAgain()},750)}else setTimeout(readyAgain,700)}
